#include <stdio.h>
#include <stdbool.h>
#include <math.h>

bool isArmstrong(int64_t n) {
    if (n < 0) {
        return false;
    }
    if (n == 0) {
        return true;
    }

    int64_t original = n;
    int d = 0;
    int64_t temp = n;

    while (temp != 0) {
        temp = temp / 10;
        d++;
    }

    int64_t sum = 0;
    temp = n;

    while (temp != 0) {
        int64_t digit = temp % 10;
        int64_t power = 1;
        for (int i = 0; i < d; i++) {
            power = power * digit;
        }
        sum = sum + power;
        temp = temp / 10;
    }

    return sum == original;
}

int main() {
    printf("%d\n", isArmstrong(0));
    printf("%d\n", isArmstrong(1));
    printf("%d\n", isArmstrong(153));
    printf("%d\n", isArmstrong(370));
    printf("%d\n", isArmstrong(371));
    printf("%d\n", isArmstrong(407));
    printf("%d\n", isArmstrong(1634));
    printf("%d\n", isArmstrong(8208));
    printf("%d\n", isArmstrong(9474));
    printf("%d\n", isArmstrong(9475));
    printf("%d\n", isArmstrong(-153));

    return 0;
}

