import java.util.*;

public class Solution {
    public static boolean isArmstrong(long n) {
        if (n < 0) return false;
        if (n == 0) return true;

        long original = n;
        int d = 0;
        long temp = n;
        while (temp > 0) {
            d++;
            temp = temp / 10;
        }

        long sum = 0;
        temp = n;
        while (temp > 0) {
            long digit = temp % 10;
            long power = 1;
            for (int i = 0; i < d; i++) {
                power = power * digit;
            }
            sum = sum + power;
            temp = temp / 10;
        }

        return sum == original;
    }

    public static void main(String[] args) {
        System.out.println(isArmstrong(0));
        System.out.println(isArmstrong(1));
        System.out.println(isArmstrong(153));
        System.out.println(isArmstrong(370));
        System.out.println(isArmstrong(371));
        System.out.println(isArmstrong(407));
        System.out.println(isArmstrong(1634));
        System.out.println(isArmstrong(8208));
        System.out.println(isArmstrong(9474));
        System.out.println(isArmstrong(9475));
    }
}
